import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Drei Zahlen beherrschen die Upload-Formulare für Bilder: 50 KB, 100 KB und 200 KB. Sie sehen ähnlich aus, aber die Bilder, die sie erzeugen, sind es nicht.</p>\n<p>Wählen Sie die falsche, scheitern Sie entweder beim Hochladen oder werfen ohne Grund Qualität weg. Wählen Sie die richtige, akzeptiert das Formular Ihre Datei beim ersten Versuch.</p>\n<p>Dieser Vergleich zeigt, was jede Größe mit einem Foto macht, wohin jede gehört und wie Sie in unter einer Minute entscheiden.</p>\n<h2 id=\"the-short-answer\">Die kurze Antwort</h2>\n<p>Nutzen Sie die größte Größe, die Ihr Portal erlaubt. Ein 200-KB-Bild sieht fast immer besser aus als ein 100-KB-Bild, und 100 KB schlägt 50 KB.</p>\n<p>Quetschen Sie nur auf 50 KB, wenn ein Formular es verlangt. Es gibt keine Belohnung dafür, kleiner zu gehen als die Grenze.</p>\n<p>Sehen Sie die Grenze als Obergrenze, nicht als Ziel. Ihre Aufgabe ist es, darunter zu bleiben und dabei so viel Qualität wie möglich zu behalten.</p>\n<p>Wenn keine Grenze angegeben ist, sind 200 KB die vernünftige Standardgröße für Fotos im Web. Sie balanciert Schärfe und Geschwindigkeit gut aus.</p>\n<h2 id=\"what-50kb-looks-like\">Wie 50 KB aussehen</h2>\n<p>Bei 50 KB bleibt ein Porträt erkennbar und brauchbar. Das Gesicht ist klar, die Kontur ist sauber und das Bild erfüllt seinen Zweck.</p>\n<p>Schaut man genauer hin, zeigt sich der Kompromiss. Haare verlieren Strähnen, Stoffe verlieren ihr Gewebe, und glatte Hintergründe können schwache Farbbänder zeigen.</p>\n<p>Text ist die Schwachstelle. Kleine Buchstaben in einem eingescannten Dokument können so weich werden, dass sie die Augen anstrengen – großer Text bleibt lesbar.</p>\n<p>Für ihre vorgesehenen Aufgaben reichen 50 KB. Pass- und Prüfungsportale wurden um diese Größe herum gebaut, und ihre Prüfer erwarten sie.</p>\n<h2 id=\"what-100kb-looks-like\">Wie 100 KB aussehen</h2>\n<p>Die Verdopplung des Budgets auf 100 KB bringt eine sichtbare Verbesserung. Kanten werden schärfer, Haut wirkt natürlicher und Hintergründe glätten sich.</p>\n<p>Ein Porträt bei 100 KB sieht in normaler Ansichtsgröße gut aus. Die meisten Menschen würden gar nicht merken, dass es komprimiert wurde.</p>\n<p>Auch Screenshots verbessern sich deutlich. Texte in Benutzeroberflächen bleiben leserlich, und kleine Beschriftungen, die bei 50 KB verschwammen, werden wieder lesbar.</p>\n<p>Deshalb sind 100 KB die ideale Größe für Lebensläufe und Jobportale. Die Größe ist klein genug für jedes System und groß genug, um professionell zu wirken.</p>\n<h2 id=\"what-200kb-looks-like\">Wie 200 KB aussehen</h2>\n<p>Bei 200 KB sieht ein typisches Webfoto fast genauso aus wie das Original. Nur ein Vergleich auf Pixelebene verrät die Komprimierung.</p>\n<p>Produktfotos profitieren am meisten. Stofftextur, Schmuckglanz und gedruckte Etiketten überleben in dieser Größe alle.</p>\n<p>Auch Infografiken und Diagramme gehören hierher. Dünne Linien und kleine Anmerkungen brauchen die zusätzlichen Daten, um scharf zu bleiben.</p>\n<p>Blogs und Onlineshops standardisieren aus genau diesem Grund auf 200 KB. Die Seiten bleiben schnell, während die Bilder überzeugend bleiben.</p>\n<h2 id=\"side-by-side\">Direkter Vergleich: Dasselbe Foto in drei Größen</h2>\n<p>Stellen Sie sich ein Porträt vor, das mit dem Handy aufgenommen wurde. Bei 200 KB hat das Haar einzelne Strähnen und das Hemd zeigt sein Gewebe.</p>\n<p>Bei 100 KB verschmelzen die Strähnen leicht und das Gewebe wird weicher. Das Gesicht sieht jedoch gleich aus – und darauf kommt es am meisten an.</p>\n<p>Bei 50 KB wird das Haar zu einer glatten Masse und der Hintergrund kann Bänder zeigen. Das Gesicht ist noch klar, aber das Foto wirkt flacher.</p>\n<p>Stellen Sie sich stattdessen einen Screenshot vor. Der Abstand wird größer: Text, der bei 200 KB gestochen scharf ist, ist bei 100 KB nur noch lesbar und bei 50 KB verschwommen.</p>\n<h2 id=\"file-size-and-dimensions\">Die Dateigröße ist nicht die ganze Geschichte</h2>\n<p>Abmessungen sind genauso wichtig wie die Dateigröße. Ein 50-KB-Bild mit 600 mal 600 Pixeln sieht weit besser aus als ein 50-KB-Bild mit 2000 mal 2000 Pixeln.</p>\n<p>Der Grund ist die Dichte. Dieselben 50 KB, verteilt auf weniger Pixel, geben jedem Pixel mehr Daten, sodass Details besser überleben.</p>\n<p>Deshalb verringert der Kompressor die Abmessungen, wenn die Qualität allein das Ziel nicht erreicht. Ein kleineres, schärferes Bild schlägt ein größeres, matschiges.</p>\n<p>Wenn ein Portal die Abmessungen festlegt, fällt dieser Ausweg weg. Dann wird die Formatwahl zum wichtigsten Hebel, und WebP hilft oft.</p>\n<h2 id=\"which-size-for-which-job\">Welche Größe für welchen Zweck?</h2>\n<p>Pass-, Visum- und Prüfungsformulare: 50 KB, weil das Portal es verlangt. Nutzen Sie den <a href=\"/de/bild-auf-50-kb-komprimieren/\">50-KB-Kompressor</a> und halten Sie die geforderten Abmessungen ein.</p>\n<p>Lebensläufe, Jobportale und Profilfotos: 100 KB. Nutzen Sie den <a href=\"/de/bild-auf-100-kb-komprimieren/\">100-KB-Kompressor</a> für das beste Gleichgewicht aus Qualität und Kompatibilität.</p>\n<p>Blogbilder, Produktfotos und Portfolioaufnahmen: 200 KB. Nutzen Sie den <a href=\"/de/bild-auf-200-kb-komprimieren/\">200-KB-Kompressor</a>, um Details zu erhalten, die verkaufen.</p>\n<p>Alles mit einer individuellen Grenze: Nutzen Sie den <a href=\"/de/bild-auf-zieldateigroesse-komprimieren/\">Zielgrößen-Kompressor</a> und tippen Sie die genaue Zahl ein, die das Formular verlangt.</p>\n<h2 id=\"format-effects\">Wie das Format den Vergleich verändert</h2>\n<p>JPG ist bei allen drei Größen das sicherste Format. Jedes Portal akzeptiert es, und es kommt mit Fotos von 50 KB bis 200 KB gut zurecht.</p>\n<p>WebP gewinnt meist bei der Qualität pro Kilobyte. Bei 50 KB kann es spürbar sauberer aussehen als JPG, aber manche älteren Portale lehnen es ab.</p>\n<p>PNG ergibt nur Sinn für Grafiken mit flachen Farben und scharfen Kanten. Für Fotos verliert es bei jeder Größe, weil es nicht genug Gewicht abwerfen kann.</p>\n<p>Die praktische Regel ist einfach: JPG, es sei denn, das Portal akzeptiert WebP und Sie brauchen die zusätzliche Qualität bei 50 KB.</p>\n<h2 id=\"loading-speed\">Und was ist mit der Ladegeschwindigkeit?</h2>\n<p>Auf einer Webseite ist der Unterschied zwischen 50 KB und 200 KB real, aber klein. Ein 200-KB-Titelbild lädt bei einer ordentlichen Verbindung immer noch schnell.</p>\n<p>Das größere Risiko ist die Anhäufung. Zehn Bilder mit 200 KB wiegen zusammen 2 MB, während zehn mit 50 KB nur 500 KB wiegen.</p>\n<p>Für eine Seite mit vielen Bildern sind 100 KB oft der richtige Mittelweg. Sie halten das Gesamtgewicht vernünftig, ohne ein einziges Foto sichtbar zu schädigen.</p>\n<p>Für ein einzelnes Titelbild verwenden Sie 200 KB. Eine große Datei verlangsamt eine Seite nicht, und der Qualitätsunterschied ist sichtbar.</p>\n<h2 id=\"decision-framework\">Ein Entscheidungsrahmen für eine Minute</h2>\n<p>Lesen Sie zuerst die Grenze. Wenn das Formular eine Zahl nennt, entscheidet diese Zahl, und die Diskussion ist beendet.</p>\n<p>Prüfen Sie als Zweites die Formatregeln. Wenn WebP abgelehnt wird, verwenden Sie JPG, auch wenn WebP etwas besser aussehen würde.</p>\n<p>Betrachten Sie als Drittes den Inhalt. Textlastige Bilder brauchen mehr Budget als Porträts, gehen Sie also eine Größe höher, wenn Text wichtig ist.</p>\n<p>Testen Sie als Viertes das Ergebnis. Komprimieren Sie auf die gewählte Größe, sehen Sie es sich in voller Größe an und reichen Sie es erst dann ein.</p>\n<ul>\n<li>Portal verlangt 50 KB: 50-KB-Tool verwenden, JPG oder WebP.</li>\n<li>Lebenslauf oder Profilfoto: 100 KB in JPG.</li>\n<li>Blog- oder Produktfoto: 200 KB in JPG oder WebP.</li>\n<li>Individuelle Grenze: die genaue Zahl ins Ziel-Tool eintippen.</li>\n<li>Textlastiges Bild: eine Größe größer gehen, als Sie zuerst geplant haben.</li>\n</ul>\n<h2 id=\"when-to-use-100kb-instead\">Wann man von 50 KB aufsteigen sollte</h2>\n<p>Viele Menschen greifen standardmäßig zu 50 KB, weil es sich sicher anfühlt. Aber wenn das Formular 100 KB erlaubt, werfen 50 KB nur Qualität weg.</p>\n<p>Ein Porträt bei 100 KB behält Haartextur und Kleidungsdetails, die 50 KB verliert. Für ein professionelles Profil ist dieser Unterschied sichtbar.</p>\n<p>Screenshots profitieren noch mehr. Kleiner Text, der bei 50 KB verschwimmt, bleibt bei 100 KB lesbar – das zählt bei Zeugnissen und Formularen.</p>\n<p>Die Regel ist einfach: Verwenden Sie immer die größte Größe, die das Formular erlaubt. Kleiner ist nicht besser, es sei denn, das Formular verlangt es.</p>\n<p>Wenn Ihr Formular 100 KB als Obergrenze nennt, verwenden Sie den <a href=\"/de/bild-auf-100-kb-komprimieren/\">100-KB-Kompressor</a> und lassen Sie ihn die Qualität innerhalb dieses Budgets maximieren.</p>\n<h2 id=\"quality-vs-dimensions\">Qualität vs. Abmessungen: Der eigentliche Kompromiss</h2>\n<p>Komprimierung hat zwei Hebel: Qualität und Abmessungen. Die Qualität steuert, wie viele Details pro Pixel weggeworfen werden, die Abmessungen steuern, wie viele Pixel es gibt.</p>\n<p>Qualität zu senken, hält das Bild groß, aber weich. Abmessungen zu verringern, hält es scharf, aber klein. Das beste Ergebnis balanciert beides aus.</p>\n<p>Das Tool versucht es zuerst mit der Qualität, weil die meisten Menschen ihre Abmessungen behalten wollen. Erst wenn die Qualität allein scheitert, geht es schrittweise nach unten.</p>\n<p>Bei einem Porträt ist ein kleiner Abmessungsschnitt oft unsichtbar. Ein Gesicht mit 500 Pixeln Breite sieht genauso aus wie mit 600, wenn es klein angezeigt wird.</p>\n<p>Bei Text sind Abmessungen wichtiger. Ein Dokument zu verkleinern, macht seine Buchstaben kleiner – bevorzugen Sie also einen Qualitätsschnitt statt eines Abmessungsschnitts, wenn Text lesbar bleiben muss.</p>\n<h2 id=\"colour-banding\">Farbbänder und wie man sie vermeidet</h2>\n<p>Farbbänder zeigen sich als sichtbare Streifen in glatten Flächen, etwa im Himmel oder an schlichten Wänden. Sie sind der häufigste sichtbare Fehler bei kleinen Größen.</p>\n<p>Bänder entstehen, weil die Komprimierung Verläufe vereinfacht. Mit nur 50 KB zur Verfügung kann ein glatter Himmel als ein paar flache Bänder gespeichert werden.</p>\n<p>Porträts mit schlichtem Hintergrund sind am stärksten betroffen. Ein Studiohintergrund, der eine einzige glatte Farbe sein sollte, kann Ringe zeigen.</p>\n<p>WebP kommt mit Verläufen bei gleicher Größe etwas besser zurecht als JPG. Wenn Bänder Sie stören, versuchen Sie zuerst die WebP-Ausgabe.</p>\n<p>Auch eine feine Textur im Hintergrund hilft. Ein Hintergrund mit leichtem Rauschen gibt dem Kompressor etwas zum Arbeiten.</p>\n<h2 id=\"choosing-between-the-three\">Ein praktischer Weg, zwischen den drei Größen zu wählen</h2>\n<p>Beginnen Sie mit dem Formular. Wenn es eine Größe nennt, ist die Wahl getroffen – hören Sie auf zu entscheiden und fangen Sie an zu komprimieren.</p>\n<p>Wenn das Formular einen Bereich angibt, nehmen Sie das obere Ende. Eine Grenze von 200 KB bedeutet, dass Sie 200 KB nutzen können, und Ihr Bild wird es Ihnen danken.</p>\n<p>Betrachten Sie als Nächstes den Inhalt. Ein Porträt übersteht 50 KB gut, während ein Screenshot oder eine Infografik 100 KB oder 200 KB braucht.</p>\n<p>Betrachten Sie auch das Publikum. Ein Foto für einen Behördenprüfer muss klar sein, nicht schön – 50 KB reichen also. Ein Portfoliofoto muss beeindrucken, verwenden Sie also 200 KB.</p>\n<p>Wenn beide Größen funktionieren, sehen Sie sich beide in der Vorschau an. Komprimieren Sie dasselbe Bild auf 50 KB und auf 100 KB, betrachten Sie sie nebeneinander und lassen Sie Ihre Augen entscheiden.</p>\n<h2 id=\"future-proofing\">Komprimierte Bilder zukunftssicher machen</h2>\n<p>Behalten Sie die Originaldatei für immer. Ein komprimiertes Bild lässt sich nie wieder in voller Qualität herstellen, egal welches Tool Sie verwenden.</p>\n<p>Speichern Sie komprimierte Kopien unter beschreibenden Namen. Ein Name, der Größe und Zweck enthält, erspart Ihnen später erneutes Komprimieren.</p>\n<p>Komprimieren Sie keine komprimierte Datei. Jede Runde fügt Schaden hinzu, und zwei Runden bei 50 KB sehen weit schlimmer aus als eine.</p>\n<p>Wenn ein Portal seine Regeln aktualisiert, komprimieren Sie frisch vom Original. Eine Datei, die für die 50-KB-Grenze des letzten Jahres gemacht wurde, passt vielleicht nicht zur 100-KB-Grenze dieses Jahres.</p>\n<p>Behandeln Sie das Original als Master und jede komprimierte Kopie als wegwerfbar. Diese Gewohnheit schützt Ihre Fotos über Jahre hinweg.</p>\n<h2 id=\"upload-speeds\">Upload-Geschwindigkeiten und langsame Verbindungen</h2>\n<p>Eine 50-KB-Datei lädt selbst bei schwacher Verbindung sofort hoch, während ein 5-MB-Original abbrechen kann. Diese Zuverlässigkeit ist ein Teil davon, warum Portale kleine Dateien verlangen.</p>\n<p>Wenn Ihre Verbindung langsam ist, komprimieren Sie, bevor Sie das Formular öffnen. Ein 5-MB-Foto zu einem Kompressor hochzuladen, verschwendet dieselbe Bandbreite, die Sie sparen wollen.</p>\n<p>Denken Sie daran, dass das Tool Dateien lokal verarbeitet. Sobald die Seite geladen ist, braucht die Komprimierung selbst überhaupt keine Verbindung.</p>\n<p>In einem gemeinsamen oder öffentlichen Netzwerk bedeuten kleine Dateien auch weniger Angriffsfläche. Ein 50-KB-Upload ist fertig, bevor jemand eingreifen kann.</p>\n<p>Für Bewerber in Gebieten mit langsamem Internet ist die 50-KB-Grenze wirklich hilfreich. Sie hält den Vorgang für alle schnell, nicht nur für diejenigen mit Glasfaser.</p>\n<h2 id=\"printing-50kb\">Kann man ein 50-KB-Bild drucken?</h2>\n<p>Ein 50-KB-Bild lässt sich drucken, aber nur in klein. Ein Druck in Passgröße ist in Ordnung, während ein A4-Druck weich und pixelig aussieht.</p>\n<p>Druck braucht etwa 300 Pixel pro Zoll. Ein 600 Pixel breites Bild druckt sauber bei zwei Zoll Breite, was für Ausweisfotos und kleine Drucke passt.</p>\n<p>Verwenden Sie eine 50-KB-Datei nie für etwas Größeres als einen kleinen Druck. Die fehlenden Details werden sofort sichtbar, sobald das Bild wächst.</p>\n<p>Behalten Sie das Original zum Drucken. Die 50-KB-Kopie existiert für Uploads, und das Original existiert für alles andere.</p>\n<p>Wenn ein Portal verlangt, dass Sie das Formular mit dem Foto ausdrucken, prüfen Sie zuerst die Druckvorschau. Ein Foto, das auf dem Bildschirm gut aussieht, kann auf Papier rau wirken.</p>\n<h2 id=\"accessibility\">Barrierefreiheit: Komprimierte Bilder für alle nutzbar machen</h2>\n<p>Ein komprimiertes Bild muss trotzdem verständlich bleiben. Ein Passfoto muss das Gesicht klar genug zeigen, dass jeder Prüfer die Person identifizieren kann.</p>\n<p>Hoher Kontrast hilft. Ein Gesicht, das sich vom Hintergrund abhebt, ist für alle leichter zu sehen – auch für Prüfer mit schlechtem Sehvermögen.</p>\n<p>Verlassen Sie sich nicht allein auf Farbe. Ein Formular, das Farbe nutzt, um Bereiche zu trennen, wird verwirrend, wenn die Komprimierung die Farben dämpft.</p>\n<p>Fügen Sie bei Webbildern immer einen beschreibenden Alt-Text hinzu. Ein 100-KB-Bild mit gutem Alt-Text dient mehr Menschen als ein perfektes Bild ohne Alt-Text.</p>\n<p>Komprimierung und Barrierefreiheit gehören zusammen. Eine klare, kontrastreiche Quelle komprimiert sich besser und ist für jeden Betrachter leichter zu lesen.</p>\n<p>Wenn Sie noch unsicher sind, beginnen Sie bei 100 KB. Es ist die nachsichtigste mittlere Größe, und Sie können nach der Vorschau des Ergebnisses nach oben oder unten gehen.</p>\n<p>Die vollständige Anleitung zur kleinsten Größe finden Sie unter <a href=\"/de/blog/bild-auf-50-kb-komprimieren-anleitung/\">Bild auf 50 KB komprimieren: Die komplette Anleitung</a>. Die praktischen Schritte stehen unter <a href=\"/de/blog/bild-auf-50-kb-komprimieren-so-geht-es/\">Bild auf 50 KB komprimieren: So geht es</a>. Die Anleitungen zu 100 KB und 200 KB behandeln die größeren Größen genauso ausführlich.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"Sind 100 KB doppelt so gut wie 50 KB?","answer":"Nicht genau doppelt, aber die Verbesserung ist leicht zu sehen. Ein 100-KB-Porträt behält spürbar mehr Haar- und Stoffdetails, und Text bleibt schärfer. Der Gewinn von 100 KB auf 200 KB ist kleiner, weil die meisten Fotos bei 100 KB schon sauber aussehen."},{"question":"Kann ein Portal erkennen, ob mein Bild 51 KB statt 50 KB hat?","answer":"Ja. Portale prüfen die exakte Bytezahl, also scheitert 51 KB an einer 50-KB-Grenze, obwohl der Unterschied winzig ist. Kompressoren zielen knapp unter die Grenze, meist um 48 bis 49,9 KB, um einen Sicherheitsspielraum zu lassen."},{"question":"Welche Größe soll ich für ein LinkedIn-Profilfoto verwenden?","answer":"LinkedIn setzt keine 50-KB-Grenze, also sind 100 KB oder 200 KB besser. Ein 200-KB-Porträt sieht am schärfsten aus, während 100 KB für einen kleinen runden Zuschnitt völlig reichen. Verwenden Sie 50 KB nur, wenn ein bestimmtes Formular es verlangt."},{"question":"Bedeutet eine größere Dateigröße immer ein besser aussehendes Bild?","answer":"Bis zu einem Punkt. Von 50 KB auf 200 KB zu gehen, verbessert ein Foto sichtbar, aber von 200 KB auf 2 MB zu gehen, fügt bei normaler Ansichtsgröße wenig hinzu. Die zusätzlichen Daten bewahren vor allem Details, die man ohne Hineinzoomen nicht sehen kann."},{"question":"Warum sieht mein Screenshot bei 50 KB schlechter aus als mein Porträt?","answer":"Screenshots enthalten scharfe Kanten und winzigen Text, die teuer zu speichern sind. Porträts haben glatte Flächen, die sich günstig komprimieren lassen. Textlastige Bilder brauchen ein größeres Budget, verwenden Sie also 100 KB oder 200 KB für Screenshots, wenn das Formular es erlaubt."},{"question":"Wenn mein Formular 200 KB erlaubt, gibt es einen Grund, 50 KB zu verwenden?","answer":"Nein. Eine kleinere Größe als erlaubt zu verwenden, wirft nur Qualität weg. Verwenden Sie immer die größte Größe, die das Formular zulässt, und lassen Sie den Kompressor die Qualität innerhalb dieses Budgets maximieren."}];
